create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text,role text not null default 'Cashier' check(role in('Developer','Admin','Manager','Cashier','Technician')),active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),name text not null,phone text unique,alt_phone text,created_at timestamptz not null default now());
create table if not exists public.suppliers(id uuid primary key default gen_random_uuid(),name text not null,phone text,address text,balance numeric(14,2) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,category text not null,sku text unique,cost numeric(14,2) not null check(cost>=0),qty numeric(14,3) not null default 0 check(qty>=0),low_stock numeric(14,3) not null default 0,track_imei boolean not null default false,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.product_units(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id),imei1 text unique,imei2 text,serial_no text,color text,status text not null default 'In Stock',created_at timestamptz not null default now());
create table if not exists public.inventory_movements(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id),movement_type text not null,qty numeric(14,3) not null,unit_cost numeric(14,2),reference_type text,reference_id uuid,created_by uuid references profiles(id),note text,created_at timestamptz not null default now());
create table if not exists public.sales(id uuid primary key default gen_random_uuid(),invoice_no text unique not null,customer_id uuid references customers(id),cashier_id uuid references profiles(id),subtotal numeric(14,2) not null default 0,discount numeric(14,2) not null default 0,total numeric(14,2) not null,paid numeric(14,2) not null default 0,status text not null default 'Paid',reversed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.sale_items(id uuid primary key default gen_random_uuid(),sale_id uuid not null references sales(id) on delete cascade,product_id uuid not null references products(id),product_unit_id uuid references product_units(id),qty numeric(14,3) not null,cost_snapshot numeric(14,2) not null,sale_price numeric(14,2) not null,check(sale_price>=cost_snapshot));
create table if not exists public.repair_jobs(id uuid primary key default gen_random_uuid(),job_no text unique not null,customer_id uuid references customers(id),brand text,model text not null,imei text,serial_no text,device_color text,complaint text not null,condition_notes text,accessories text,deadline timestamptz,technician_id uuid references profiles(id),received_by uuid references profiles(id),status text not null default 'Received' check(status in('Received','Assigned','Repairing','Ready for Handover','Completed','Delivered','Warranty','Cancelled','Unrepairable')),quote_total numeric(14,2) not null default 0,paid_total numeric(14,2) not null default 0,parent_warranty_job_id uuid references repair_jobs(id),created_at timestamptz not null default now(),completed_at timestamptz,delivered_at timestamptz);
create table if not exists public.repair_parts(id uuid primary key default gen_random_uuid(),repair_id uuid not null references repair_jobs(id),product_id uuid not null references products(id),qty numeric(14,3) not null default 1,cost_snapshot numeric(14,2) not null,customer_charge numeric(14,2) not null default 0,state text not null default 'Used',created_at timestamptz not null default now());
create table if not exists public.repair_handovers(id uuid primary key default gen_random_uuid(),repair_id uuid not null references repair_jobs(id),from_user uuid references profiles(id),to_user uuid references profiles(id),accepted_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.repair_status_history(id uuid primary key default gen_random_uuid(),repair_id uuid not null references repair_jobs(id),status text not null,changed_by uuid references profiles(id),note text,created_at timestamptz not null default now());
create table if not exists public.technician_rates(technician_id uuid primary key references profiles(id),percentage numeric(5,2) not null default 50 check(percentage between 0 and 100),updated_at timestamptz not null default now());
create table if not exists public.technician_ledger(id uuid primary key default gen_random_uuid(),technician_id uuid not null references profiles(id),repair_id uuid references repair_jobs(id),entry_type text not null check(entry_type in('earning','payment','bonus','deduction','reversal')),amount numeric(14,2) not null check(amount>=0),description text,created_by uuid references profiles(id),created_at timestamptz not null default now());
create table if not exists public.expenses(id uuid primary key default gen_random_uuid(),description text not null,category text not null,amount numeric(14,2) not null check(amount>=0),spent_at timestamptz not null default now(),created_by uuid references profiles(id));
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id),title text not null,text text,kind text not null default 'info',read_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.feedback_tokens(id uuid primary key default gen_random_uuid(),token uuid unique not null default gen_random_uuid(),sale_id uuid references sales(id),repair_id uuid references repair_jobs(id),expires_at timestamptz,used_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.feedback(id uuid primary key default gen_random_uuid(),token_id uuid references feedback_tokens(id),rating int not null check(rating between 1 and 5),service_rating int check(service_rating between 1 and 5),staff_rating int check(staff_rating between 1 and 5),repair_rating int check(repair_rating between 1 and 5),comment text,created_at timestamptz not null default now());
create table if not exists public.audit_log(id uuid primary key default gen_random_uuid(),actor_id uuid references profiles(id),action text not null,entity_type text not null,entity_id uuid,reason text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.complete_pos_sale(p_invoice_no text,p_product_id uuid,p_qty numeric,p_sale_price numeric,p_cashier_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_product products%rowtype;v_sale uuid;begin select * into v_product from products where id=p_product_id for update;if not found then raise exception 'Product not found';end if;if p_qty<=0 then raise exception 'Quantity must be positive';end if;if v_product.qty<p_qty then raise exception 'Insufficient stock';end if;if p_sale_price<v_product.cost then raise exception 'Sale price cannot be below cost price';end if;insert into sales(invoice_no,cashier_id,subtotal,total,paid,status) values(p_invoice_no,p_cashier_id,p_sale_price*p_qty,p_sale_price*p_qty,p_sale_price*p_qty,'Paid') returning id into v_sale;insert into sale_items(sale_id,product_id,qty,cost_snapshot,sale_price) values(v_sale,p_product_id,p_qty,v_product.cost,p_sale_price);update products set qty=qty-p_qty where id=p_product_id;insert into inventory_movements(product_id,movement_type,qty,unit_cost,reference_type,reference_id,note) values(p_product_id,'SALE_OUT',-p_qty,v_product.cost,'sale',v_sale,'POS sale');return v_sale;end $$;
create index if not exists idx_repair_deadline on repair_jobs(status,deadline);create index if not exists idx_ledger_tech on technician_ledger(technician_id,created_at desc);create index if not exists idx_inventory_product on inventory_movements(product_id,created_at desc);
